BEGIN; DO $check$ BEGIN IF (SELECT md5(prosrc) FROM pg_proc WHERE oid='lm_submit_order(jsonb)'::regprocedure)<>'4e158de7a48a5d4bb2950d116e908ce3' THEN RAISE EXCEPTION 'Unexpected intake revision';END IF; END $check$; CREATE TABLE public.lm_upload_reservations ( id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES auth.users(id), state text NOT NULL DEFAULT 'reserved' CHECK(state IN ('reserved','complete','released')), created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz ); ALTER TABLE public.lm_upload_reservations ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.lm_upload_reservations FROM PUBLIC,anon,authenticated,service_role; CREATE FUNCTION public.lm_manage_upload_reservation(action text,owner uuid,reservation uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $body$ DECLARE row public.lm_upload_reservations; total_bytes numeric; owner_bytes numeric; owner_objects bigint; pending_all bigint; pending_owner bigint; attempts bigint; BEGIN IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'LM_QUOTA_REQUIRES_READ_COMMITTED';END IF; IF action IS NULL OR action NOT IN ('reserve','complete','release') OR owner IS NULL THEN RAISE EXCEPTION 'Invalid reservation request';END IF; PERFORM pg_advisory_xact_lock(hashtextextended('lm-private-designs:quota-v1',0)); IF action='reserve' THEN IF reservation IS NOT NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=owner) THEN RAISE EXCEPTION 'Invalid upload owner';END IF; SELECT count(*) INTO attempts FROM public.lm_upload_reservations r WHERE r.owner_id=owner AND r.created_at>now()-interval '24 hours'; SELECT attempts+count(*) INTO attempts FROM public.lm_verified_assets a WHERE a.owner_id=owner AND a.created_at>now()-interval '24 hours' AND NOT EXISTS(SELECT 1 FROM public.lm_upload_reservations r WHERE r.id=a.id); IF attempts>=10 THEN RAISE EXCEPTION 'LM_UPLOAD_RATE_LIMIT';END IF; SELECT count(*),count(*) FILTER(WHERE owner_id=owner) INTO pending_all,pending_owner FROM public.lm_upload_reservations WHERE state='reserved'; SELECT coalesce(sum(CASE WHEN metadata->>'size' ~ '^[0-9]+$' THEN (metadata->>'size')::numeric ELSE 5000000 END),0),coalesce(sum(CASE WHEN name LIKE owner::text||'/%' THEN CASE WHEN metadata->>'size' ~ '^[0-9]+$' THEN (metadata->>'size')::numeric ELSE 5000000 END ELSE 0 END),0),count(*) FILTER(WHERE name LIKE owner::text||'/%') INTO total_bytes,owner_bytes,owner_objects FROM storage.objects WHERE bucket_id='lm-private-designs'; IF total_bytes+(pending_all+1)*10000000>250000000 THEN RAISE EXCEPTION 'LM_UPLOAD_STORE_QUOTA';END IF; IF owner_bytes+(pending_owner+1)*10000000>50000000 OR owner_objects+(pending_owner+1)*2>40 THEN RAISE EXCEPTION 'LM_UPLOAD_OWNER_QUOTA';END IF; INSERT INTO public.lm_upload_reservations(owner_id) VALUES(owner) RETURNING * INTO row;RETURN row.id; END IF; SELECT * INTO row FROM public.lm_upload_reservations WHERE id=reservation AND owner_id=owner FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Upload reservation unavailable';END IF; IF action='complete' THEN IF row.state='complete' THEN RETURN row.id;END IF; IF row.state<>'reserved' OR NOT EXISTS(SELECT 1 FROM public.lm_verified_assets WHERE id=row.id AND owner_id=owner) OR (SELECT count(*) FROM storage.objects WHERE bucket_id='lm-private-designs' AND name IN(owner::text||'/'||row.id::text||'/original',owner::text||'/'||row.id::text||'/preview') AND metadata->>'size' ~ '^[0-9]+$' AND (metadata->>'size')::numeric BETWEEN 1 AND 5000000)<>2 THEN RAISE EXCEPTION 'Upload completion not verified';END IF; UPDATE public.lm_upload_reservations SET state='complete',finished_at=now() WHERE id=row.id;RETURN row.id; END IF; IF row.state='released' THEN RETURN row.id;END IF; IF row.state<>'reserved' OR EXISTS(SELECT 1 FROM public.lm_verified_assets WHERE id=row.id) OR EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='lm-private-designs' AND name LIKE owner::text||'/'||row.id::text||'/%') THEN RAISE EXCEPTION 'Upload cleanup not verified';END IF; UPDATE public.lm_upload_reservations SET state='released',finished_at=now() WHERE id=row.id;RETURN row.id; END $body$; REVOKE ALL ON FUNCTION public.lm_manage_upload_reservation(text,uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.lm_manage_upload_reservation(text,uuid,uuid) TO service_role; CREATE FUNCTION public.lm_guard_design_quota() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $body$ DECLARE rows_count bigint; used_bytes bigint; BEGIN IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'LM_QUOTA_REQUIRES_READ_COMMITTED';END IF; PERFORM pg_advisory_xact_lock(hashtextextended('lm-design-history:'||NEW.owner_id::text,0)); SELECT count(*),coalesce(sum(octet_length(payload::text)),0) INTO rows_count,used_bytes FROM public.lm_design_history WHERE owner_id=NEW.owner_id AND id<>NEW.id; IF rows_count>=100 OR used_bytes+octet_length(NEW.payload::text)>5000000 THEN RAISE EXCEPTION 'LM_DESIGN_QUOTA';END IF; RETURN NEW; END $body$; REVOKE ALL ON FUNCTION public.lm_guard_design_quota() FROM PUBLIC,anon,authenticated,service_role; CREATE TRIGGER lm_design_quota BEFORE INSERT OR UPDATE ON public.lm_design_history FOR EACH ROW EXECUTE FUNCTION public.lm_guard_design_quota(); ALTER TABLE public.lm_user_data ADD CONSTRAINT lm_user_data_size_limit CHECK(octet_length(data::text)<=1000000); COMMIT;